package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Frequency_getCumPct_TriageGen2Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testGetCumPct_EmptyFrequencyReturnsNaN() {
        Frequency frequency = new Frequency();
        // sumFreq is 0, should return Double.NaN
        assertEquals(Double.NaN, frequency.getCumPct(10), DELTA);
    }

    @Test
    public void testGetCumPct_SingleValue() {
        Frequency frequency = new Frequency();
        frequency.addValue(10);
        // sumFreq = 1, getCumFreq(10) = 1 -> 1/1 = 1.0
        assertEquals(1.0, frequency.getCumPct(10), DELTA);
        // getCumFreq(5) = 0 -> 0/1 = 0.0
        assertEquals(0.0, frequency.getCumPct(5), DELTA);
    }

    @Test
    public void testGetCumPct_MultipleValuesInteger() {
        Frequency frequency = new Frequency();
        frequency.addValue(1);
        frequency.addValue(2);
        frequency.addValue(2);
        frequency.addValue(3);
        frequency.addValue(3);
        frequency.addValue(3);
        // Total sumFreq = 6
        // Values: 1 (freq 1), 2 (freq 2), 3 (freq 3)

        // CumFreq(1) = 1 -> 1/6
        assertEquals(1.0 / 6.0, frequency.getCumPct(1), DELTA);
        // CumFreq(2) = 1 + 2 = 3 -> 3/6 = 0.5
        assertEquals(0.5, frequency.getCumPct(2), DELTA);
        // CumFreq(3) = 1 + 2 + 3 = 6 -> 6/6 = 1.0
        assertEquals(1.0, frequency.getCumPct(3), DELTA);
        // CumFreq(4) (not present but > max) = 6 -> 1.0
        assertEquals(1.0, frequency.getCumPct(4), DELTA);
        // CumFreq(0) (not present and < min) = 0 -> 0.0
        assertEquals(0.0, frequency.getCumPct(0), DELTA);
    }

    @Test
    public void testGetCumPct_StringValues() {
        Frequency frequency = new Frequency();
        frequency.addValue("apple");
        frequency.addValue("banana");
        frequency.addValue("cherry");
        // Total sumFreq = 3

        // CumFreq("apple") = 1 -> 1/3
        assertEquals(1.0 / 3.0, frequency.getCumPct("apple"), DELTA);
        // CumFreq("banana") = 2 -> 2/3
        assertEquals(2.0 / 3.0, frequency.getCumPct("banana"), DELTA);
        // CumFreq("cherry") = 3 -> 1.0
        assertEquals(1.0, frequency.getCumPct("cherry"), DELTA);
        // CumFreq("date") = 3 -> 1.0
        assertEquals(1.0, frequency.getCumPct("date"), DELTA);
    }

    @Test
    public void testGetCumPct_DoubleValues() {
        Frequency frequency = new Frequency();
        frequency.addValue(1.1);
        frequency.addValue(2.2);
        // Total sumFreq = 2

        assertEquals(0.5, frequency.getCumPct(1.1), DELTA);
        assertEquals(1.0, frequency.getCumPct(2.2), DELTA);
        assertEquals(1.0, frequency.getCumPct(3.3), DELTA);
        assertEquals(0.0, frequency.getCumPct(0.0), DELTA);
    }
}
